import type { Finish } from "@/core/types";
import { DIMENSION_KEYS, type ScooterCategory, type ScooterPart } from "./types";

const FINISHES: Finish[] = ["gloss", "matte", "anodized", "raw"];
const CATEGORIES = Object.keys(DIMENSION_KEYS) as ScooterCategory[];

/**
 * Validates raw catalog JSON (e.g. generated by data agents / the scraper
 * pipeline) and fails loudly with the offending part id and field.
 */
export function validateScooterCatalog(raw: unknown): ScooterPart[] {
  if (!Array.isArray(raw)) throw new Error("scooter catalog must be an array");
  const seen = new Set<string>();
  return raw.map((p: Record<string, unknown>, i) => {
    const where = `scooter-parts.json[${i}] (${String(p?.id)})`;
    const fail = (msg: string): never => {
      throw new Error(`${where}: ${msg}`);
    };
    if (typeof p.id !== "string" || !p.id) fail("missing id");
    if (seen.has(p.id as string)) fail("duplicate id");
    seen.add(p.id as string);
    for (const k of ["name", "brand", "colorHex"]) if (typeof p[k] !== "string") fail(`missing ${k}`);
    if (!CATEGORIES.includes(p.category as ScooterCategory)) fail(`unknown category "${p.category}"`);
    if (typeof p.weightGrams !== "number") fail("weightGrams must be a number");
    if (!FINISHES.includes(p.finish as Finish)) fail(`finish must be one of ${FINISHES.join(", ")}`);
    const dims = (p.dimensions ?? {}) as Record<string, unknown>;
    for (const k of DIMENSION_KEYS[p.category as ScooterCategory]) {
      if (typeof dims[k] !== "number") fail(`dimensions.${k} (mm) is required for ${p.category}`);
    }
    if (!Array.isArray(p.retailers) || p.retailers.length === 0) fail("needs at least one retailer");
    return p as unknown as ScooterPart;
  });
}
